# Book Your Admissions — Upcoming Deadline Checker
# Compatible with n8n Python mode without imports.

# Current date in YYYY-MM-DD format.
# Update this date when testing on a different day.
today = "2026-10-25"

today_year = int(today[0:4])
today_month = int(today[5:7])
today_day = int(today[8:10])

# Convert a date to a sortable day number.
# This supports month and year boundaries.
def day_number(year, month, day):
    total = year * 365 + day
    for m in range(1, month):
        if m == 2:
            total += 28
        elif m in (4, 6, 9, 11):
            total += 30
        else:
            total += 31

    # Add leap days from earlier years.
    total += (year - 1) // 4 - (year - 1) // 100 + (year - 1) // 400
    return total

today_num = day_number(today_year, today_month, today_day)
upcoming = []

for item in _items:
    row = item["json"]

    deadline = str(row.get("application_deadline", "")).strip()
    source_url = str(row.get("deadline_source_url", "")).strip()

    if deadline.lower() in ("", "nan", "none", "null"):
        continue

    if source_url.lower() in ("", "nan", "none", "null"):
        continue

    if len(deadline) != 10 or deadline[4] != "-" or deadline[7] != "-":
        continue

    try:
        year = int(deadline[0:4])
        month = int(deadline[5:7])
        day = int(deadline[8:10])
    except:
        continue

    if month < 1 or month > 12 or day < 1 or day > 31:
        continue

    deadline_num = day_number(year, month, day)

    if today_num <= deadline_num <= today_num + 30:
        upcoming.append({
            "college_name": row.get("college_name", ""),
            "course_name": row.get("course_name", ""),
            "application_deadline": deadline,
            "deadline_source_url": source_url
        })

return [{
    "json": {
        "checked_on": today,
        "upcoming_count": len(upcoming),
        "upcoming_deadlines": upcoming,
        "message": (
            "Candidate deadlines found. Verify official sources."
            if upcoming
            else "No verified upcoming deadlines found."
        )
    }
}]
